@Serializable data class ZoneRequest(val code: String, val name: String, val description: String? = null)
@Serializable data class RouteRequest(val code: String, val name: String, val zoneId: String, val description: String? = null, val validFrom: String)
@Serializable data class AssignmentRequest(val routeId: String, val validFrom: String, val reason: String? = null)
@Serializable data class ProductRequest(val code: String, val name: String, val category: String, val unit: String)
@Serializable data class CustomerRequest(val code: String, val name: String, val document: String? = null, val customerType: String, val phone: String? = null)
@Serializable data class PriceRequest(val productId: String, val customerType: String, val amount: String, val currency: String, val effectiveFrom: String, val effectiveTo: String? = null, val reason: String)
@Serializable data class ParameterRequest(val key: String, val value: String, val valueType: String, val unit: String? = null, val effectiveFrom: String, val reason: String? = null)
@Serializable data class WorkdayRequest(val code: String, val routeId: String, val unitId: String, val workDate: String, val plannedStartTime: String, val plannedEndTime: String? = null)
