@Serializable data class AuditDto(val id: String, val actorUserId: String, val action: String, val entityType: String, val entityId: String, val occurredAt: String, val reason: String? = null, val beforeData: String? = null, val afterData: String? = null)
@Serializable data class HistoryDto(val provider: ProviderDto, val assignments: List<SimpleRow>, val collections: List<SimpleRow> = emptyList(), val directDeliveries: List<SimpleRow> = emptyList(), val quality: List<SimpleRow> = emptyList(), val incidents: List<SimpleRow> = emptyList(), val weeklySummaries: List<SimpleRow> = emptyList(), val settlements: List<SimpleRow> = emptyList(), val payments: List<SimpleRow> = emptyList(), val unavailableSources: List<String> = emptyList())
@Serializable data class OperationalReportDto(val dateFrom: String? = null, val dateTo: String? = null, val providers: List<ProviderDto>, val zones: List<SimpleRow> = emptyList(), val routes: List<SimpleRow> = emptyList(), val workdays: List<SimpleRow> = emptyList(), val collections: List<SimpleRow> = emptyList(), val directDeliveries: List<SimpleRow> = emptyList(), val receptions: List<SimpleRow> = emptyList(), val reconciliations: List<SimpleRow> = emptyList(), val quality: List<SimpleRow> = emptyList(), val classifications: List<SimpleRow> = emptyList(), val incidents: List<SimpleRow> = emptyList(), val sourcesUnavailable: List<String> = emptyList())

fun Route.operationsRoutes(dataSource: HikariDataSource?, auth: AuthService?) {
    route("/api/v1") {
        get("/providers") { withUser(auth, call, Permission.VIEW_PROVIDERS) { db(dataSource, call) { it.providers() } } }
        post("/providers") { val request = call.receive<ProviderRequest>(); withUser(auth, call, Permission.MANAGE_PROVIDERS) { user -> db(dataSource, call) { it.createProvider(request, user.userId) } } }
        get("/providers/{id}") { withUser(auth, call, Permission.VIEW_PROVIDERS) { db(dataSource, call) { it.provider(requireId(call)) } } }
        put("/providers/{id}") { val request = call.receive<ProviderRequest>(); withUser(auth, call, Permission.MANAGE_PROVIDERS) { user -> db(dataSource, call) { it.updateProvider(requireId(call), request, user.userId) } } }
        post("/providers/{id}/activate") { withUser(auth, call, Permission.MANAGE_PROVIDERS) { user -> db(dataSource, call) { it.changeStatus("provider", requireId(call), "ACTIVE", user.userId, "PROVIDER") } } }
        post("/providers/{id}/deactivate") { withUser(auth, call, Permission.MANAGE_PROVIDERS) { user -> db(dataSource, call) { it.changeStatus("provider", requireId(call), "INACTIVE", user.userId, "PROVIDER") } } }
        post("/providers/{id}/assignments") { val request = call.receive<AssignmentRequest>(); withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.assign(requireId(call), request, user.userId) } } }
        get("/providers/{id}/history") { withUser(auth, call, Permission.MANAGE_PROVIDERS, allowSelf = true) { user ->
            val requested = requireId(call)
            if (user.role.name == "PROVEEDOR" && user.providerId != requested) forbidden(call) else db(dataSource, call) { it.history(requested) }
        } }

        get("/zones") { withUser(auth, call, Permission.VIEW_ROUTES) { db(dataSource, call) { it.simple("zone") } } }
        post("/zones") { val request = call.receive<ZoneRequest>(); withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.createZone(request, user.userId) } } }
        put("/zones/{id}") { val request = call.receive<ZoneRequest>(); withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.updateZone(requireId(call), request, user.userId) } } }
        post("/zones/{id}/activate") { withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.changeStatus("zone", requireId(call), "ACTIVE", user.userId, "ZONE") } } }
        post("/zones/{id}/deactivate") { withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.changeStatus("zone", requireId(call), "INACTIVE", user.userId, "ZONE") } } }
        get("/routes") { withUser(auth, call, Permission.VIEW_ROUTES) { db(dataSource, call) { it.simpleRoutes(call.request.queryParameters["zoneId"]) } } }
        post("/routes") { val request = call.receive<RouteRequest>(); withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.createRoute(request, user.userId) } } }
        put("/routes/{id}") { val request = call.receive<RouteRequest>(); withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.updateRoute(requireId(call), request, user.userId) } } }
        post("/routes/{id}/activate") { withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.changeStatus("route", requireId(call), "ACTIVE", user.userId, "ROUTE") } } }
        post("/routes/{id}/deactivate") { withUser(auth, call, Permission.MANAGE_ROUTES) { user -> db(dataSource, call) { it.changeStatus("route", requireId(call), "INACTIVE", user.userId, "ROUTE") } } }
        get("/collection-units") { withUser(auth, call, Permission.VIEW_WORKDAYS) { db(dataSource, call) { it.simple("collection_unit") } } }
        post("/collection-units") { val request = call.receive<CollectionUnitRequest>(); withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.createUnit(request, user.userId) } } }
        put("/collection-units/{id}") { val request = call.receive<CollectionUnitRequest>(); withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.updateUnit(requireId(call), request, user.userId) } } }
        post("/collection-units/{id}/activate") { withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.changeStatus("collection_unit", requireId(call), "ACTIVE", user.userId, "COLLECTION_UNIT") } } }
        post("/collection-units/{id}/deactivate") { withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.changeStatus("collection_unit", requireId(call), "INACTIVE", user.userId, "COLLECTION_UNIT") } } }
        get("/workdays") { withUser(auth, call, Permission.VIEW_WORKDAYS) { db(dataSource, call) { it.workdays(call.request.queryParameters["date"], call.request.queryParameters["routeId"], call.request.queryParameters["unitId"]) } } }
        post("/workdays") { val request = call.receive<WorkdayRequest>(); withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.createWorkday(request, user.userId) } } }
        get("/workdays/{id}") { withUser(auth, call, Permission.VIEW_WORKDAYS) { db(dataSource, call) { it.workday(requireId(call)) } } }
        put("/workdays/{id}") { val request = call.receive<WorkdayRequest>(); withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.updateWorkday(requireId(call), request, user.userId) } } }
        post("/workdays/{id}/cancel") { withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.changeStatus("collection_workday", requireId(call), "CANCELLED", user.userId, "WORKDAY") } } }
        post("/workdays/{id}/staff") { val request = call.receive<WorkdayStaffRequest>(); withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.assignStaff(requireId(call), request, user.userId) } } }
        get("/workdays/{id}/staff") { withUser(auth, call, Permission.VIEW_WORKDAYS) { db(dataSource, call) { it.staff(requireId(call)) } } }
        delete("/workdays/{id}/staff/{userId}") { withUser(auth, call, Permission.MANAGE_WORKDAYS) { user -> db(dataSource, call) { it.removeStaff(requireId(call), call.parameters["userId"]!!, user.userId) } } }

        get("/catalog/products") { withUser(auth, call, Permission.VIEW_CATALOG) { db(dataSource, call) { it.simple("product") } } }
        get("/catalog/products/{id}") { withUser(auth, call, Permission.VIEW_CATALOG) { db(dataSource, call) { it.catalog("product", requireId(call)) } } }
        post("/catalog/products") { val request = call.receive<ProductRequest>(); withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.createProduct(request, user.userId) } } }
        put("/catalog/products/{id}") { val request = call.receive<ProductRequest>(); withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.updateCatalog("product", requireId(call), request.code, request.name, user.userId) } } }
        post("/catalog/products/{id}/deactivate") { withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.changeStatus("product", requireId(call), "INACTIVE", user.userId, "PRODUCT") } } }
        post("/catalog/products/{id}/activate") { withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.changeStatus("product", requireId(call), "ACTIVE", user.userId, "PRODUCT") } } }
        get("/catalog/customers") { withUser(auth, call, Permission.VIEW_CATALOG) { db(dataSource, call) { it.simple("customer") } } }
        get("/catalog/customers/{id}") { withUser(auth, call, Permission.VIEW_CATALOG) { db(dataSource, call) { it.catalog("customer", requireId(call)) } } }
        post("/catalog/customers") { val request = call.receive<CustomerRequest>(); withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.createCustomer(request, user.userId) } } }
        put("/catalog/customers/{id}") { val request = call.receive<CustomerRequest>(); withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.updateCatalog("customer", requireId(call), request.code, request.name, user.userId) } } }
        post("/catalog/customers/{id}/deactivate") { withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.changeStatus("customer", requireId(call), "INACTIVE", user.userId, "CUSTOMER") } } }
        post("/catalog/customers/{id}/activate") { withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.changeStatus("customer", requireId(call), "ACTIVE", user.userId, "CUSTOMER") } } }
        post("/catalog/prices") { val request = call.receive<PriceRequest>(); withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.createPrice(request, user.userId) } } }
        get("/catalog/prices/{productId}") { withUser(auth, call, Permission.VIEW_CATALOG) { db(dataSource, call) { it.prices(requireId(call)) } } }
        get("/catalog/prices/{productId}/resolve") { withUser(auth, call, Permission.VIEW_CATALOG) { db(dataSource, call) { it.resolvePrice(requireId(call), call.request.queryParameters["customerType"] ?: "PUBLIC", call.request.queryParameters["date"] ?: LocalDate.now().toString()) } } }
        post("/catalog/prices/{id}/deactivate") { withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.changeStatus("product_price", requireId(call), "INACTIVE", user.userId, "PRICE") } } }
        post("/catalog/prices/{id}/close") { withUser(auth, call, Permission.MANAGE_CATALOG) { user -> db(dataSource, call) { it.closePrice(requireId(call), user.userId) } } }

        get("/parameters") { withUser(auth, call, Permission.VIEW_PARAMETERS) { db(dataSource, call) { it.parameters() } } }
        post("/parameters") { val request = call.receive<ParameterRequest>(); withUser(auth, call, Permission.MANAGE_PARAMETERS) { user -> db(dataSource, call) { it.createParameter(request, user.userId) } } }
        get("/parameters/{key}") { withUser(auth, call, Permission.VIEW_PARAMETERS) { db(dataSource, call) { it.parameterHistory(call.parameters["key"]!!) } } }
        post("/parameters/{key}/deactivate") { withUser(auth, call, Permission.MANAGE_PARAMETERS) { user -> db(dataSource, call) { it.deactivateParameter(call.parameters["key"]!!, user.userId) } } }
        get("/audit") { withUser(auth, call, Permission.VIEW_AUDIT) { db(dataSource, call) { it.audit(call.request.queryParameters["actor"], call.request.queryParameters["action"], call.request.queryParameters["entityType"], call.request.queryParameters["entityId"], call.request.queryParameters["page"]?.toIntOrNull() ?: 0, call.request.queryParameters["pageSize"]?.toIntOrNull() ?: 50) } } }
        get("/reports/operational") { withUser(auth, call, Permission.VIEW_REPORTS) { db(dataSource, call) { it.report(call.request.queryParameters["dateFrom"], call.request.queryParameters["dateTo"], call.request.queryParameters["providerId"], call.request.queryParameters["zoneId"], call.request.queryParameters["routeId"]) } } }
    }
